using Retrocore.Machines.Apple2;
using Retrocore.Media;
using System.Security.Cryptography;

namespace Retrocore.Tests;

/// <summary>
///  Verifies the generated slot-seven firmware preserves the complete original byte stream and ABI.
/// </summary>
[TestClass]
public class Slot7RomTests
{
    /// <summary>
    ///  Checks all 256 generated bytes, including padding, signatures and the entry trailer.
    /// </summary>
    [TestMethod]
    public void GeneratedRomMatchesOriginalAndAllocatesNothingOnAccess()
    {
        long before = GC.GetAllocatedBytesForCurrentThread();
        ReadOnlySpan<byte> bytes = Slot7Rom.Bytes;
        long allocated = GC.GetAllocatedBytesForCurrentThread() - before;
        allocated.Should().Be(0);
        bytes.Length.Should().Be(256);
        Convert.ToHexString(SHA256.HashData(bytes)).Should().Be("83EA6ECB07D0CACCEFD88E0594CDE3EBED34E4FDA6A54B75BB33C31D67D55836");
        Slot7Rom.DriverEntry.Should().Be(0xC740);
        Slot7Rom.DeviceInfo.Should().Be(0xC7FE);
        typeof(Slot7Rom).TypeInitializer.Should().BeNull();
    }

    /// <summary>
    ///  Executes compiled status/read/write/error paths with the emulated CPU, not an assembler proxy.
    /// </summary>
    /// <param name="command">The ProDOS command.</param>
    /// <param name="readOnly">Whether the disk rejects writes.</param>
    /// <param name="expectedError">The returned ProDOS error.</param>
    [TestMethod]
    [DataRow((byte)0, true, (byte)0)]
    [DataRow((byte)1, true, (byte)0)]
    [DataRow((byte)2, false, (byte)0)]
    [DataRow((byte)2, true, (byte)0x2B)]
    [DataRow((byte)99, true, (byte)1)]
    public void CompiledDriverPreservesRegistersAndReportsCarry(byte command, bool readOnly, byte expectedError)
    {
        byte[] image = new byte[1536];
        Array.Fill(image, (byte)0x5A, startIndex: 512, count: 512);
        MemoryBlockDevice disk = new(image, readOnly);
        Apple2Machine machine = new(Apple2Model.IIe, new Apple2Roms(new byte[16384], new byte[4096]), disk);
        machine.Run(cycles: 7);
        machine.Processor.Registers = new()
        {
            ProgramCounter = 0x2000, StackPointer = 0xFD, X = 0xAA, Y = 0xBB, Status = StatusRegister.Unused
        };

        machine.Bus.SetRam(auxiliary: false, address: 0x2000, value: 0x20);
        machine.Bus.SetRam(auxiliary: false, address: 0x2001, value: (byte)(Slot7Rom.DriverEntry & 255));
        machine.Bus.SetRam(auxiliary: false, address: 0x2002, value: (byte)(Slot7Rom.DriverEntry >> 8));
        machine.Bus.SetRam(auxiliary: false, address: 0x42, command);
        machine.Bus.SetRam(auxiliary: false, address: 0x45, value: 8);
        machine.Bus.SetRam(auxiliary: false, address: 0x46, value: 1);
        for (int i = 0; i < 512; i++) { machine.Bus.SetRam(auxiliary: false, (ushort)(0x800 + i), value: 0x66); }
        bool returned = false;
        for (int i = 0; i < 32; i++)
        {
            machine.StepInstruction().Status.Should().Be(ProcessorExecutionStatus.InstructionComplete);
            if (machine.Processor.Registers.ProgramCounter == 0x2003)
            {
                returned = true;
                break;
            }
        }

        returned.Should().BeTrue();
        ProcessorRegisters registers = machine.Processor.Registers;
        registers.Accumulator.Should().Be(expectedError);
        registers.Status.HasFlag(StatusRegister.Carry).Should().Be(expectedError != 0);
        registers.StackPointer.Should().Be(0xFD);
        registers.X.Should().Be(command == 0 ? (byte)3 : (byte)0xAA);
        registers.Y.Should().Be(command == 0 ? (byte)0 : (byte)0xBB);
        if (command == 1) { machine.Bus.MainMemory[0x800].Should().Be(0x5A); }
        if (command == 2 && !readOnly)
        {
            byte[] block = new byte[512];
            disk.ReadBlock(block: 1, block);
            block.Should().OnlyContain(value => value == 0x66);
        }

        byte[] firmware = Enumerable.Range(0, 256).Select(offset => machine.Bus.Peek((ushort)(0xC700 + offset))).ToArray();
        Convert.ToHexString(SHA256.HashData(firmware)).Should().Be(readOnly
            ? "83EA6ECB07D0CACCEFD88E0594CDE3EBED34E4FDA6A54B75BB33C31D67D55836"
            : "8410DC635F05B3205156949A727E9EC8AEC7E86963B012085B3A3B20F951360D");
    }
}
